{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C06"],
      "claim": "GHRP-6, a peptide, had <1% oral bioavailability in humans, directly demonstrating that peptide drugs with multiple polar residues have very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Octreotide, a cyclic octapeptide, had absolute oral bioavailability of 0.6 ± 0.4% in healthy volunteers, a direct absolute F measurement for a peptide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor, had 0.5% oral bioavailability in humans, supporting low F for peptide-like molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Plecanatide, a peptide, showed negligible systemic availability after oral dosing in humans, consistent with very low F for large peptides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "HEX, a hexapeptide, had 0.3 ± 0.1% oral bioavailability in humans, another peptide with F far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Macimorelin, a small peptidomimetic, had good oral bioavailability in patients; however, its small size and lack of the query's fatty-acid/PEG modifications limit transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large fatty-acid-modified peptide. Multiple human oral bioavailability measurements for peptide/peptidomimetic drugs are <2%, and the only good-oral-F analogue is a much smaller peptidomimetic lacking the query's polar/lipid modifications. Thus the query is predicted to have F <20%.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule itself.",
    "C12's record (paliperidone) does not match its provided SMILES (a peptide), so it was excluded as unreliable.",
    "Most evidence is for related but not identical peptides; exact F for the query is unknown.",
    "Fasted-state condition is specified but most records do not report prandial state; food effects could alter absorption."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

